Ejemplo: Redis/Java
Con Redis:
public Producto obtenerProducto(Long id) {
    String key = "producto:" + id;
    Producto producto =
        (Producto) redisTemplate
            .opsForValue()
            .get(key);
    if(producto != null) {
        return producto;
    }
    producto = productoRepository
        .findById(id)
        .orElseThrow();
    redisTemplate
        .opsForValue()
        .set(key, producto);
    return producto;
}
